targets = [7/3, 11/4, 2024/5, 109/11, 3/71, 5/204]
known_input = 11/3

print("Checking if any target input r_i satisfies r_i = -known_input, r_i = 1 - known_input, or r_i = 1/known_input.")
for r in targets:
    r_neg = -known_input
    r_one_minus = 1 - known_input
    r_reciprocal = 1 / known_input

    matches = []
    if abs(r - r_neg) < 1e-9:
        matches.append("=-r")
    if abs(r - r_one_minus) < 1e-9:
        matches.append("=1-r")
    if abs(r - r_reciprocal) < 1e-9:
        matches.append("=1/r")

    if matches:
        print(f"Found match for {r}: {', '.join(matches)}")
    else:
        print(f"No direct relationship found for {r}")
